+    }
+  }
+
+  PhiNode* r = new PhiNode(phi->in(0), type());
+  phase->set_type_bottom(r);
+  for (uint i = 1; i < phi->req(); i++) {
+    r->init_req(i, phi->in(i)->in(1));
+  }
+  return r;
